SELECT 
FROM chatbi.bid_biz_prepose

    AND province = #{province}
    AND city = #{city}
    AND industry = #{industry}
    AND info_type = #{infoType}
    AND tenderer LIKE CONCAT('%', #{tenderer}, '%')

        AND (
          title LIKE CONCAT('%', #{keyword}, '%')
          OR project_name LIKE CONCAT('%', #{keyword}, '%')
          OR product LIKE CONCAT('%', #{keyword}, '%')
          OR keywords LIKE CONCAT('%', #{keyword}, '%')
        )

    AND bidding_budget >= #{minBudgetYuan}
    AND bidding_budget <= #{maxBudgetYuan}
    AND publish_time >= #{beginDate}
    AND publish_time <= #{endDate}

ORDER BY publish_time DESC, id DESC
LIMIT #{limit}

SELECT product AS keyword,
       COUNT(*) AS count,
       COALESCE(SUM(bidding_budget), 0) AS amount
FROM chatbi.bid_biz_prepose


        AND tenderer LIKE CONCAT('%', #{tenderer}, '%')


        AND province IN

            #{p}


    AND publish_time >= #{beginDate}
    AND publish_time <= #{endDate}
    AND product IS NOT NULL AND product != ''

GROUP BY product
ORDER BY count DESC
LIMIT #{limit}

SELECT
province AS bucket_key, IFNULL(city, '') AS bucket_key, industry AS bucket_key, DATE_FORMAT(publish_time, '%Y-%m') AS bucket_key, CONCAT(YEAR(publish_time), '-Q', QUARTER(publish_time)) AS bucket_key, YEAR(publish_time) AS bucket_key, DATE_FORMAT(publish_time, '%Y-%m-%d') AS bucket_key,
CASE WHEN bidding_budget IS NULL OR bidding_budget <= 0 THEN '0-未披露' WHEN bidding_budget < 100000 THEN '1-小于10万' WHEN bidding_budget < 500000 THEN '2-10万-50万' WHEN bidding_budget < 1000000 THEN '3-50万-100万' WHEN bidding_budget < 3000000 THEN '4-100万-300万' WHEN bidding_budget < 5000000 THEN '5-300万-500万' WHEN bidding_budget < 10000000 THEN '6-500万-1000万' ELSE '7-大于等于1000万' END AS bucket_key,
province AS bucket_key,
COUNT(*) AS cnt, COALESCE(SUM(bidding_budget), 0) AS sum_amount, COALESCE(SUM(CASE WHEN bidding_budget IS NOT NULL AND bidding_budget > 0 THEN 1 ELSE 0 END), 0) AS disclosed_cnt FROM chatbi.bid_biz_prepose
title LIKE CONCAT('%', #{kw}, '%') OR project_name LIKE CONCAT('%', #{kw}, '%') OR product LIKE CONCAT('%', #{kw}, '%') OR keywords LIKE CONCAT('%', #{kw}, '%')
AND province IN
#{p}
AND bidding_budget >= #{minBudget} AND bidding_budget <= #{maxBudget} AND publish_time >= #{beginDate} AND publish_time <= #{endDate}
GROUP BY bucket_key ORDER BY cnt DESC LIMIT #{limit}
